//! Accessibility over upstream's markup (ex-709, ADR-012).
//!
//! - `ICONS_CSS` is styles.scss's `.rtl-mirror` rule (css/styles.scss:
//!   679-683, generated by tools/goldens/icons.mjs): an icon created with
//!   `mirror: true` (icons.tsx:22-47) flips in a right-to-left document;
//! - [`ACCESSIBLE_NAMES`] names the icon-only controls upstream renders
//!   without one (radix's `DropdownMenu.Trigger` and `Tabs.Trigger` with
//!   an aria-hidden icon as the only child), each with upstream's own
//!   English string for it, so axe's `button-name` passes;
//! - [`SCROLL_REGIONS`] (the command palette's list) get a tab stop, and
//!   [`ACCESSIBILITY_CSS`] raises upstream's secondary text to 4.5:1;
//! - the reduced-motion rules upstream has for the ported components
//!   (TopPicksDnD.scss:47-49) are in their stylesheets.

use excali_ui::accessibility::{
    AccessibleName, ACCESSIBILITY_CSS, ACCESSIBLE_NAMES, SCROLL_REGIONS,
};
use excali_ui::icons::{ICONS, ICONS_CSS};
use excali_ui::library_sidebar::library_text;
use excali_ui::main_menu::menu_text;
use excali_ui::top_picks_dnd::TOP_PICKS_DND_CSS;

#[test]
fn icons_css_flips_mirrored_icons_in_rtl_documents() {
    assert!(ICONS_CSS.starts_with("/* Generated by tools/goldens/icons.mjs"));
    assert!(ICONS_CSS
        .ends_with(":root[dir=rtl] .excalidraw .rtl-mirror {\n  transform: scaleX(-1);\n}\n"));
    // the class it matches is the one the mirrored icons carry, and only they
    for i in ICONS {
        if let Some(svg) = i.svg(excali_scene::shape::Theme::Light) {
            assert_eq!(svg.contains("class=\"rtl-mirror\""), i.mirror, "{}", i.name);
        }
    }
    let mirrored: Vec<&str> = ICONS.iter().filter(|i| i.mirror).map(|i| i.name).collect();
    assert_eq!(
        mirrored,
        ["questionCircle", "clone", "GroupIcon", "UngroupIcon"]
    );
}

#[test]
fn accessible_names_are_upstreams_english_strings() {
    let names: Vec<(&str, &str)> = ACCESSIBLE_NAMES
        .iter()
        .map(|n: &AccessibleName| (n.selector, n.key))
        .collect();
    assert_eq!(
        names,
        [
            (".main-menu-trigger", "buttons.menu"),
            (
                ".sidebar-tab-trigger[id$=\"-trigger-search\"]",
                "search.title"
            ),
            (
                ".sidebar-tab-trigger[id$=\"-trigger-library\"]",
                "toolBar.library"
            ),
            (
                ".library-menu-dropdown-container .dropdown-menu-button",
                "labels.more_options"
            ),
        ]
    );
    // each text is the string the fixtures read from upstream's en.json
    for n in ACCESSIBLE_NAMES {
        let upstream = match n.key {
            "buttons.menu" | "search.title" => menu_text(n.key),
            _ => library_text(n.key),
        };
        assert_ne!(upstream, n.key, "{} has no English string", n.key);
        assert_eq!(n.text, upstream, "{}", n.key);
    }
}

#[test]
fn top_picks_outline_stops_marching_under_reduced_motion() {
    assert!(TOP_PICKS_DND_CSS
        .contains("animation: excalidraw-top-picks-dnd-march 0.8s linear infinite;"));
    assert!(TOP_PICKS_DND_CSS.contains(
        "@media (prefers-reduced-motion: reduce) {\n  .excalidraw .top-picks-dnd__outline rect {\n    animation: none;\n  }\n}"
    ));
}

#[test]
fn the_command_list_is_a_scroll_region_and_the_contrast_rules_are_scoped() {
    assert_eq!(SCROLL_REGIONS, [".command-palette-dialog .commands"]);
    assert!(ACCESSIBILITY_CSS.contains(
        ".excalidraw .dropdown-menu .dropdown-menu-item > .dropdown-menu-item__shortcut {\n  opacity: 0.7;\n}"
    ));
    // light only: the dark theme's grey on the dark island already passes
    assert!(ACCESSIBILITY_CSS.contains(
        ".excalidraw:not(.theme--dark) .command-palette-dialog .shortcut .shortcut-desc,\n\
         .excalidraw:not(.theme--dark) .library-menu-items__no-items__hint {\n  color: var(--color-gray-70);\n}"
    ));
}
